CREATE TABLE cti_items (
    id         INTEGER PRIMARY KEY,
    feed_id    INTEGER NOT NULL REFERENCES cti_feeds (id) ON DELETE CASCADE,
    guid       TEXT    NOT NULL,
    title      TEXT    NOT NULL,
    link       TEXT    NOT NULL DEFAULT '',
    summary    TEXT    NOT NULL DEFAULT '',
    published  TEXT    NOT NULL,
    countries  TEXT    NOT NULL DEFAULT '', -- comma-separated, surrounded by commas for LIKE matching
    sectors    TEXT    NOT NULL DEFAULT '', -- idem
    created_at TEXT    NOT NULL, regulations TEXT NOT NULL DEFAULT '',
    UNIQUE (feed_id, guid)
);
INSERT INTO "cti_items" VALUES(16,1,'https://www.cert.cyber.gouv.fr/alerte/CERTFR-2026-ALE-006/','Multiples vulnérabilités dans Sonicwall Secure Mobile Access (15 juillet 2026)','https://www.cert.cyber.gouv.fr/alerte/CERTFR-2026-ALE-006/','Le 14 juillet 2026, Sonicwall a publié un avis de sécurité concernant deux vulnérabilités affectant les Secure Mobile Access (SMA) 1000. La vulnérabilité critique CVE-2026-15409 permet une falsification de requêtes côté serveur (SSRF) de la part d''un attaquant non authentifié. La vulnérabilité...','2026-07-15T00:00:00Z',',FR,','','2026-11-13T13:30:16Z','');
INSERT INTO "cti_items" VALUES(17,1,'https://www.cert.cyber.gouv.fr/alerte/CERTFR-2026-ALE-007/','Multiples vulnérabilités dans WordPress (20 juillet 2026)','https://www.cert.cyber.gouv.fr/alerte/CERTFR-2026-ALE-007/','Le 17 juillet 2026, WordPress a publié un correctif pour deux vulnérabilités : CVE-2026-60137 : une injection SQL (SQLi) ; CVE-2026-63030 : celle-ci permet un contournement de la politique de sécurité. Un attaquant peut exploiter ces deux vulnérabilités, de manière combinée, pour obtenir une...','2026-07-20T00:00:00Z',',FR,','','2026-11-13T13:30:16Z','');
INSERT INTO "cti_items" VALUES(18,1,'https://www.cert.cyber.gouv.fr/alerte/CERTFR-2026-ALE-008/','Multiples vulnérabilités dans Microsoft Sharepoint (22 juillet 2026)','https://www.cert.cyber.gouv.fr/alerte/CERTFR-2026-ALE-008/','Le 14 juillet 2026, à l''occasion de sa mise à jour mensuelle, Microsoft a publié, entre autres, des correctifs pour deux vulnérabilités critiques affectant SharePoint. Les vulnérabilités CVE-2026-50522 et CVE-2026-58644 permettent à un attaquant non authentifié d''exécuter du code arbitraire à...','2026-07-22T00:00:00Z',',FR,','','2026-11-13T13:30:16Z','');
INSERT INTO "cti_items" VALUES(19,1,'https://www.cert.cyber.gouv.fr/alerte/CERTFR-2026-ALE-009/','Multiples vulnérabilités dans SonicWall Secure Mobile Access (02 septembre 2026)','https://www.cert.cyber.gouv.fr/alerte/CERTFR-2026-ALE-009/','Le 01 septembre 2026, SonicWall a publié un avis de sécurité concernant deux vulnérabilités affectant les Secure Mobile Access (SMA) 1000. La vulnérabilité critique CVE-2026-83548 permet une falsification de requêtes côté serveur (SSRF) de la part d''un attaquant non authentifié. La vulnérabilité...','2026-09-02T00:00:00Z',',FR,','','2026-11-13T13:30:16Z','');
INSERT INTO "cti_items" VALUES(21,1,'https://www.cert.cyber.gouv.fr/alerte/CERTFR-2026-ALE-011/','Multiples vulnérabilités dans Citrix NetScaler ADC et Gateway (28 septembre 2026)','https://www.cert.cyber.gouv.fr/alerte/CERTFR-2026-ALE-011/','**[Mise à jour du 05 octobre 2026]** Le 4 octobre 2026, Citrix a publié un avis concernant une nouvelle vulnérabilité (CVE-2026-88779) permettant un déni de service à distance. La CISA indique que cette vulnérabilité est activement exploitée. **[Mise à jour du 30 septembre 2026]** Dans un billet...','2026-09-28T00:00:00Z',',FR,US,','','2026-11-13T13:30:16Z','');
INSERT INTO "cti_items" VALUES(23,1,'https://www.cert.cyber.gouv.fr/alerte/CERTFR-2026-ALE-013/','[MàJ] Multiples vulnérabilités dans Ivanti Connect Secure (ICS) (14 octobre 2026)','https://www.cert.cyber.gouv.fr/alerte/CERTFR-2026-ALE-013/','[Mise à jour du 2 novembre 2026] Le 29 octobre 2026, Ivanti a mis à jour son avis de sécurité du 13 octobre 2026 pour ajouter deux vulnérabilités (CVE-2026-111357 et CVE-2026-118527). Celles-ci permettent à un attaquant authentifié d''élever ses privilèges et de téléverser un fichier arbitraire...','2026-10-14T00:00:00Z',',FR,',',manufacturing,','2026-11-13T13:30:16Z','');
INSERT INTO "cti_items" VALUES(24,1,'https://www.cert.cyber.gouv.fr/alerte/CERTFR-2026-ALE-014/','[Màj] Multiples vulnérabilités dans PHP (21 octobre 2026)','https://www.cert.cyber.gouv.fr/alerte/CERTFR-2026-ALE-014/','**[Mise à jour du 26 octobre 2026]** Le 23 octobre 2026, PHP a publié un avis de sécurité concernant la vulnérabilité CVE-2026-115560. Celle-ci permet une exécution de code arbitraire à distance. L''éditeur estime que les conditions d''exploitation exigent une combinaison d''options de configuration...','2026-10-21T00:00:00Z',',FR,','','2026-11-13T13:30:16Z','');
INSERT INTO "cti_items" VALUES(25,1,'https://www.cert.cyber.gouv.fr/alerte/CERTFR-2026-ALE-015/','[MàJ] Vulnérabilité dans OpenSSH (05 novembre 2026)','https://www.cert.cyber.gouv.fr/alerte/CERTFR-2026-ALE-015/','[Mise à jour du 6 novembre 2026] Cette vulnérabilité porte l''identifiant CVE-2026-123158. Alpine a publié un bulletin de sécurité (cf. section Documentation) concernant cette vulnérabilité. Le CERT-FR précise que toute installation de correctif ou modification de la configuration doit...','2026-11-05T00:00:00Z',',FR,','','2026-11-13T13:30:16Z','');
INSERT INTO "cti_items" VALUES(28,2,'https://www.cert.cyber.gouv.fr/avis/CERTFR-2026-AVI-1488/','Multiples vulnérabilités dans Google Chrome (10 novembre 2026)','https://www.cert.cyber.gouv.fr/avis/CERTFR-2026-AVI-1488/','De multiples vulnérabilités ont été découvertes dans Google Chrome. Elles permettent à un attaquant de provoquer un problème de sécurité non spécifié par l''éditeur. Google indique que la vulnérabilité CVE-2026-125350 est activement exploitée.','2026-11-10T00:00:00Z',',FR,','','2026-11-13T13:30:16Z','');
INSERT INTO "cti_items" VALUES(73,4,'/node/25791','Siemens Desigo, Gridscale','https://www.cisa.gov/news-events/ics-advisories/icsa-26-316-02','View CSAF Summary On October 21, 2026, the Node.js project released security updates addressing a critical vulnerability in the Brotli decoder bundled with Node.js, commonly referred to as "Node2Shell" (tracked as CVE-2026-111497). The vulnerability is an out-of-bounds write that could allow a remote attacker to cause memory corruption and potentially execute arbitrary code. This advisory covers the status of impact of various Siemens software products. Siemens has released new versions for the affected products and recommends to update to the latest versions. The following versions of Siemens Desigo, Gridscale are affected: Desigo CC family V8 vers:all/* (CVE-2026-111497) Desigo CC family V9 vers:all/* (CVE-2026-111497) Gridscale X DSA vers:intdot/>=5.3| = V5.3 < V5.4 Product Status: known_affected, known_not_affected Remediations Vendor fix Update to V5.4 or later version Gridscale X PSS®E < V36.8.0 Product Status: known_affected, known_not_affected Remediations Vendor fix Update to V36.8.0 or later version Additional Metrics Relevant CWE: CWE-787 Out-of-bounds Write CVSS Version Base Score Base Severity Vector String 3.1 9.8 CRITICAL CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H View CVE Details Acknowledgments Siemens ProductCERT reported this vulnerability to CISA. General Recommendations Operators of critical power systems (e.g. TSOs or DSOs) worldwide are usually required by regulations to build resilience into the power grids by applying multi-level redundant secondary protection schemes. It is therefore recommended that the operators check whether appropriate resilient protection measures are in place. The risk of cyber incidents impacting the grid''s reliability can thus be minimized by virtue of the grid design. Siemens strongly recommends applying the provided security updates using the corresponding tooling and documented procedures made available with the product. If supported by the product, an automated means to apply the security updates across multi…','2026-11-12T12:00:00Z',',US,','','2026-11-13T13:30:17Z','');
INSERT INTO "cti_items" VALUES(74,4,'/node/25793','Siemens RUGGEDCOM APE1808','https://www.cisa.gov/news-events/ics-advisories/icsa-26-316-05','View CSAF Summary Palo Alto Networks has published information on vulnerabilities in PAN-OS related to PHP2Shell vulnerabilities. This advisory lists the related Siemens Industrial products affected by these vulnerabilities. Customers are advised to consult and implement the workarounds provided in Palo Alto Networks'' upstream security notifications. The following versions of Siemens RUGGEDCOM APE1808 are affected: RUGGEDCOM APE1808 vers:all/* (CVE-2026-109618, CVE-2026-109619) CVSS Vendor Equipment v3 9.8 Siemens RUGGEDCOM APE1808 1 Vulnerability Use After Free Background Critical Infrastructure Sectors: Critical Manufacturing Countries/Areas Deployed: Worldwide Company Headquarters Location: Germany Vulnerabilities Expand All + CVE-2026-109618 PHP uses longjmp() for out-of-memory (OOM) errors to exit the current context and abort handling of the request. Some contexts may not properly account for this scenario and leave request memory in an uninitialized state before performing an allocation. The subsequent request cleanup procedure may read or branch on this memory. Multiple OOM strategies can consistently trigger this condition and lead to remote code execution (RCE). Read More 1 Affected Product RUGGEDCOM APE1808 with Palo Alto Networks PAN-OS (10.2 All, 11.1 All, 11.2 All, 12.1 All, 12.2 All) Product Status: known_affected Remediations Vendor fix Upgrade to corresponding available PAN-OS version. Contact customer support to receive additional patch and update information. Additional Metrics Relevant CWE: CWE-416 Use After Free CVSS Version Base Score Base Severity Vector String 3.1 9.8 CRITICAL CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H View CVE Details CVE-2026-109619 PHP has various global state that temporarily points into request memory. In some scenarios, global state may not be correctly reset, or may be repopulated after being reset. The global state may then refer to request memory even after it has been freed. Subsequent requests may read or branch…','2026-11-12T12:00:00Z',',DE,US,',',manufacturing,','2026-11-13T13:30:17Z','');
INSERT INTO "cti_items" VALUES(75,4,'/node/25792','Siemens RUGGEDCOM APE1808','https://www.cisa.gov/news-events/ics-advisories/icsa-26-316-04','View CSAF Summary Palo Alto Networks has published information on a vulnerability in PAN-OS related to the Node2Shell vulnerability. This advisory lists the related Siemens Industrial products affected by this vulnerability. Customers are advised to consult and implement the workarounds provided in Palo Alto Networks'' upstream security notifications. The following versions of Siemens RUGGEDCOM APE1808 are affected: RUGGEDCOM APE1808 vers:all/* (CVE-2026-111497) CVSS Vendor Equipment v3 9.8 Siemens RUGGEDCOM APE1808 1 Vulnerability Out-of-bounds Write Background Critical Infrastructure Sectors: Critical Manufacturing Countries/Areas Deployed: Worldwide Company Headquarters Location: Germany Vulnerabilities CVE-2026-111497 A buffer overflow vulnerability in the Brotli decoder (c/dec/decode.c) in Google Brotli versions 1.0.3 through 1.2.0 on all platforms allows a remote unauthenticated attacker to corrupt adjacent decoder state memory, disclose sensitive memory contents, cause a denial of service, or potentially execute arbitrary code using a crafted Brotli-compressed stream. Users need to update any Brotli libraries or binaries between 1.0.3 through 1.2.0 to the latest available version: 1.0.10 or 1.1.1 or 1.2.1. Read More 1 Affected Product RUGGEDCOM APE1808 with Palo Alto Networks PAN-OS Product Status: known_affected Remediations Vendor fix Upgrade to corresponding available PAN-OS version. Contact customer support to receive additional patch and update information. Additional Metrics Relevant CWE: CWE-787 Out-of-bounds Write CVSS Version Base Score Base Severity Vector String 3.1 9.8 CRITICAL CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H View CVE Details Acknowledgments Siemens ProductCERT reported this vulnerability to CISA. General Recommendations As a general security measure, Siemens strongly recommends protecting network access to devices with appropriate mechanisms. In order to operate the devices in a protected IT environment, Siemens recommends configurin…','2026-11-12T12:00:00Z',',DE,US,',',manufacturing,','2026-11-13T13:30:17Z','');
INSERT INTO "cti_items" VALUES(76,4,'/node/25790','Siemens Building Automation and Energy Products','https://www.cisa.gov/news-events/ics-advisories/icsa-26-316-01','View CSAF Summary On October 21, 2026, the PHP project and security researchers disclosed two critical, unauthenticated remote code execution vulnerabilities in the core PHP language runtime known as "php2shell" (tracked as CVE-2026-109618 and CVE-2026-109619). This advisory covers the status of impact of various Siemens software products. As a general security measure, Siemens strongly recommends to protect network access to devices with appropriate mechanisms. In order to operate the devices in a protected IT environment, Siemens recommends to configure the environment according to Siemens'' operational guidelines, and to follow the recommendations in the product manuals. Siemens is actively monitoring the situation and assessing the implications of these vulnerabilities on our portfolio. Because this evaluation is ongoing, our findings are subject to change as new technical details and vendor updates emerge. We will publish updated findings, guidance, and remediation recommendations as soon as they become available. Siemens has released new versions for several affected products and recommends to update to the latest versions. Siemens is preparing further fixes and recommends mitigations for products where fixes are not or not yet available. The following versions of Siemens Building Automation and Energy Products are affected: AMIS TS vers:all/* (CVE-2026-109618, CVE-2026-109619) blueplanet 360 NX3 M6 WM OD IISX vers:all/* (CVE-2026-109618, CVE-2026-109619) blueplanet 360 NX3 M6 WM OD IISX - S vers:all/* (CVE-2026-109618, CVE-2026-109619) Energy Engage V2.0SP9 vers:all/* (CVE-2026-109618, CVE-2026-109619) Energy Engage V3.1SP1 vers:all/* (CVE-2026-109618, CVE-2026-109619) Heliox Rapid vers:all/* ()Local Monitoring bt-monitoring-vm vers:intdot/<20261103 (CVE-2026-109618, CVE-2026-109619) Spectrum Power 3 vers:all/* (CVE-2026-109619) Spectrum Power 4 vers:all/*, vers:all/*, vers:all/* (CVE-2026-109618, CVE-2026-109619, CVE-2026-109618, CVE-2026-109619, CVE-2026-10…','2026-11-12T12:00:00Z',',US,',',energy,','2026-11-13T13:30:17Z','');
INSERT INTO "cti_items" VALUES(77,4,'/node/25789','Siemens Industrial Edge Management','https://www.cisa.gov/news-events/ics-advisories/icsa-26-316-03','View CSAF Summary Siemens is currently assessing the impact of Node2Shell (CVE-2026-111497) on Industrial Edge. Please check your Industrial Edge Management (IEM) setup: - No Management Applications installed: No action is required. Although the affected Brotli library is included in the IEM software stack, the affected functionality is not used or exposed. The same applies to IEDK. - Management Applications installed: Follow the specific mitigations until a fix is available. - Device Applications installed: Follow the specific mitigations until a fix is available. For Siemens-managed services, Industrial Edge Hub and Industrial Edge Management Cloud, appropriate Firewall/WAF protection has already been implemented. Siemens has released new versions for several affected products and recommends to update to the latest versions. Siemens is preparing further fixes and recommends specific mitigations for products where fixes are not or not yet available. The following versions of Siemens Industrial Edge Management are affected: Cloud Connector Configurator vers:intdot/<1.24.3 (CVE-2026-111497) Common Configurator (CC on IEM) vers:all/* (CVE-2026-111497) Common Configurator on Device (CC on Edge) vers:all/* (CVE-2026-111497) Data Flow Monitoring vers:intdot/<3.0.18 (CVE-2026-111497) Databus Configurator vers:intdot/<4.0.1 (CVE-2026-111497) DataXess Configurator vers:intdot/<1.5.7 (CVE-2026-111497) Edge OPC UA Server Configurator vers:intdot/<2.3.10 (CVE-2026-111497) Flow Creator Configurator vers:intdot/<1.15.1 (CVE-2026-111497) Industrial Edge Hub vers:all/* (CVE-2026-111497) Industrial Edge Management Cloud vers:all/* (CVE-2026-111497) CVSS Vendor Equipment v3 9.8 Siemens Cloud Connector Configurator 1 Vulnerability Out-of-bounds Write Background Critical Infrastructure Sectors: Critical Manufacturing Countries/Areas Deployed: Worldwide Company Headquarters Location: Germany Vulnerabilities CVE-2026-111497 A buffer overflow vulnerability in the Brotli decoder (c/dec/d…','2026-11-12T12:00:00Z',',DE,US,',',digital,manufacturing,','2026-11-13T13:30:17Z','');
INSERT INTO "cti_items" VALUES(78,4,'/node/25787','CISA Adds Six Known Exploited Vulnerabilities to Catalog','https://www.cisa.gov/news-events/alerts/2026/11/10/cisa-adds-six-known-exploited-vulnerabilities-catalog','CISA has added six new vulnerabilities to its Known Exploited Vulnerabilities (KEV) Catalog , based on evidence of active exploitation. CVE-2026-20320 Cisco BroadWorks Improper Restriction of XML External Entity Reference Vulnerability CVE-2026-111560 Barracuda Networks Multiple Products OS Command Injection Vulnerability CVE-2026-111793 Openwave Messaging Limited Webtop Media Transcoder Incorrect Resource Transfer Between Spheres Vulnerability CVE-2026-116606 Barracuda Networks Email Security Gateway (ESG) Authentication Bypass Using an Alternate Path or Channel Vulnerability CVE-2026-124194 Microsoft Office Outlook Missing User Interaction for Potentially Unsafe Action Vulnerability CVE-2026-125350 Google Chromium Use-After-Free Vulnerability These types of vulnerabilities are a frequent attack vector for malicious cyber actors and pose significant risks to the federal enterprise. Binding Operational Directive (BOD) 26-04: Prioritizing Security Updates Based on Risk establishes vulnerability management requirements for Federal Civilian Executive Branch (FCEB) agencies. BOD 26-04 reinforces the importance of the KEV Catalog and requires federal agencies to prioritize rapid remediation of high-risk vulnerabilities, specifically those identified by Common Vulnerabilities and Exposures (CVEs) listed in CISA’s KEV Catalog on publicly exposed assets that grant total control of the asset post-exploitation, while deferring action for lower-risk vulnerabilities. BOD 26-04 further establishes basic expectations for when agencies must check whether threat actors compromised the system before the patch was applied. While BOD 26-04 applies only to FCEB agencies, CISA encourages all organizations to adopt risk-based vulnerability management and prioritize remediation of KEV Catalog vulnerabilities . CISA will continue to add vulnerabilities to the catalog that meet the specified criteria . Aware of an exploited vulnerability not currently listed in the KEV Catalog? Submit it f…','2026-11-10T12:00:00Z',',US,','','2026-11-13T13:30:17Z','');
