INSERT INTO "vulnerabilities" VALUES('UBUNTU-CVE-2026-35189','["CVE-2026-35189"]','Issue summary: A certificate with many nameRelativeToCRLIssuer CRL distribution points causes disproportionate heap growth when OpenSSL caches X.509 extensions.','Issue summary: A certificate with many nameRelativeToCRLIssuer CRL distribution points causes disproportionate heap growth when OpenSSL caches X.509 extensions. Impact summary: Receiving a crafted certificate from a malicious peer can lead to significant memory pressure and possible Denial of Service in clients or in servers that solicit client certificates. CWE: CWE-770: Allocation of Resources Without Limits or Throttling Description: A certificate or a set of certificates that fits under the limit for size of certificates accepted from the peer (~100 KiB) can result in allocation of several hundred MiB of resident memory on the receiving side during a normal TLS handshake.  This may be enough to crash the client or server, if multiple concurrent connections lead to similarly large memory allocations. The fix postpones processing of the CRL distribution points extensions in certificates to the time when the processed value is required for CRL processing. This avoids keeping large memory allocations for a long time when such certificates are received. FIPS impact: no The affected code is outside the FIPS module boundary.','MEDIUM','2026-09-29T00:00:00Z','2026-10-22T04:31:00.650053584Z','["https://ubuntu.com/security/CVE-2026-35189","https://www.cve.org/CVERecord?id=CVE-2026-35189","https://openssl-library.org/news/secadv/20260929.txt","https://ubuntu.com/security/notices/USN-8847-1","https://ubuntu.com/security/notices/USN-8847-2"]','{"id":"UBUNTU-CVE-2026-35189","affected":[{"package":{"name":"openssl","ecosystem":"Ubuntu:Pro:14.04:LTS","purl":"pkg:deb/ubuntu/openssl?arch=source\u0026distro=esm-infra-legacy%2Ftrusty"},"ranges":[{"type":"ECOSYSTEM","events":[{"introduced":"0"},{"fixed":"1.0.1f-1ubuntu2.27+esm17"}]}]},{"pack