INSERT INTO "vulnerabilities" VALUES('USN-8625-1','[]','openssl vulnerability','It was discovered that OpenSSL incorrectly allocated memory buffers in the
SSL/TLS state machine when receiving handshake data. A remote attacker
could possibly use this issue to cause OpenSSL to consume excessive memory,
leading to a denial of service. This issue is known as the "HollowByte"
denial of service.','','2026-07-30T13:38:32Z','2026-07-30T20:30:20.851624858Z','["https://ubuntu.com/security/notices/USN-8625-1","https://launchpad.net/bugs/2161371"]','{"id":"USN-8625-1","affected":[{"package":{"name":"openssl","ecosystem":"Ubuntu:22.04:LTS","purl":"pkg:deb/ubuntu/openssl?arch=source\u0026distro=jammy"},"ranges":[{"type":"ECOSYSTEM","events":[{"introduced":"0"},{"fixed":"3.0.2-0ubuntu1.26"}]}]},{"package":{"name":"openssl","ecosystem":"Ubuntu:24.04:LTS","purl":"pkg:deb/ubuntu/openssl?arch=source\u0026distro=noble"},"ranges":[{"type":"ECOSYSTEM","events":[{"introduced":"0"},{"fixed":"3.0.13-0ubuntu3.12"}]}]},{"package":{"name":"openssl","ecosystem":"Ubuntu:26.04:LTS","purl":"pkg:deb/ubuntu/openssl?arch=source\u0026distro=resolute"},"ranges":[{"type":"ECOSYSTEM","events":[{"introduced":"0"},{"fixed":"3.5.5-1ubuntu3.3"}]}]}]}','2026-11-13T13:31:42Z',0,'',-1.0,-1.0);
CREATE TABLE "webhooks" (
    id         INTEGER PRIMARY KEY,
    name       TEXT    NOT NULL,
    kind       TEXT    NOT NULL CHECK (kind IN ('slack', 'mattermost', 'teams', 'generic', 'email')),
    url        TEXT    NOT NULL, -- webhook URL (secret), or comma-separated e-mail recipients
    enabled    INTEGER NOT NULL DEFAULT 1,
    last_error TEXT    NOT NULL DEFAULT '',
    created_at TEXT    NOT NULL,
    digests    INTEGER NOT NULL DEFAULT 1,  -- receives the periodic digests
    alerts     TEXT    NOT NULL DEFAULT ''  -- immediate alerts: '' none, 'priority', 'severe'
, group_id INTEGER
    REFERENCES asset_groups (id) ON DELETE RESTRICT);
